1	// Package server exposes the frozen public surface of SignalWatch.
2	//
3	// Besides the baseline process health check, the server accepts in-memory
4	// metric samples at /api/v1/metrics. All new responses use JSON. Metric state
5	// is process-local and is lost on restart.
6	package server
7	
8	import (
9		"bytes"
10		"encoding/json"
11		"io"
12		"math"
13		"mime"
14		"net/http"
15		"net/url"
16		"regexp"
17		"sort"
18		"strconv"
19		"strings"
20		"sync"
21	)
22	
23	// Version is the baseline release identifier.
24	const Version = "0.1.0"
25	
26	const metricsPath = "/api/v1/metrics"
27	
28	var identPattern = regexp.MustCompile(`^[a-zA-Z_][a-zA-Z0-9_]*$`)
29	
30	type health struct {
31		Status  string `json:"status"`
32		Service string `json:"service"`
33		Version string `json:"version"`
34	}
35	
36	// series is one uniquely identified time series: name + full label set.
37	type series struct {
38		name   string
39		typ    string
40		labels map[string]string
41	
42		// counter/gauge state
43		value float64
44	
45		// histogram state
46		bucketBounds []float64 // strictly increasing, fixed at first write
47		bucketCounts []int64   // cumulative counts per bound, len == len(bucketBounds)
48		count        int64
49		sum          float64
50	}
51	
52	type metricStore struct {
53		mu     sync.RWMutex
54		series map[string]*series
55	
56		// alert rules keyed by rule id; guarded by mu so rule replacement and
57		// alert evaluation are atomic with metric commits.
58		rules map[string]*alertRule
59	}
60	
61	func newMetricStore() *metricStore {
62		return &metricStore{
63			series: make(map[string]*series),
64			rules:  make(map[string]*alertRule),
65		}
66	}
67	
68	// validatedSample is a sample that passed all format and value checks.
69	type validatedSample struct {
70		key     string
71		name    string
72		typ     string
73		labels  map[string]string
74		value   float64
75		buckets []float64 // non-nil for histograms
76	}
77	
78	// checkAndApply validates the batch against the current state (and against
79	// itself) and then commits it in array order. A false result signals a type or
80	// bucket-boundary conflict; in that case no state is mutated.
81	func (s *metricStore) checkAndApply(batch []validatedSample) bool {
82		s.mu.Lock()
83		defer s.mu.Unlock()
84	
85		// First pass: conflict detection against committed state and earlier
86		// samples in the same batch.
87		resolved := make(map[string]*series, len(batch))
88		for _, sm := range batch {
89			existing, ok := s.series[sm.key]
90			if !ok {
91				if shadow, seen := resolved[sm.key]; seen {
92					existing, ok = shadow, true
93				}
94			}
95			if ok {
96				if existing.typ != sm.typ {
97					return false
98				}
99				if sm.typ == "histogram" && !equalBuckets(existing.bucketBounds, sm.buckets) {
100					return false
101				}
102				resolved[sm.key] = existing
103				continue
104			}
105			resolved[sm.key] = &series{typ: sm.typ, bucketBounds: sm.buckets}
106		}
107	
108		// Second pass: commit in order.
109		for _, sm := range batch {
110			cur, ok := s.series[sm.key]
111			if !ok {
112				cur = &series{
113					name:         sm.name,
114					typ:          sm.typ,
115					labels:       sm.labels,
116					bucketBounds: append([]float64(nil), sm.buckets...),
117				}
118				if sm.typ == "histogram" {
119					cur.bucketCounts = make([]int64, len(sm.buckets))
120				}
121				s.series[sm.key] = cur
122			}
123			switch sm.typ {
124			case "counter":
125				cur.value += sm.value
126			case "gauge":
127				cur.value = sm.value
128			case "histogram":
129				cur.count++
130				cur.sum += sm.value
131				for i, bound := range cur.bucketBounds {
132					if sm.value <= bound {
133						cur.bucketCounts[i]++
134					}
135				}
136			}
137		}
138		return true
139	}
140	
141	type seriesOutput struct {
142		Name    string            `json:"name"`
143		Type    string            `json:"type"`
144		Labels  map[string]string `json:"labels"`
145		Value   *float64          `json:"value,omitempty"`
146		Count   *int64            `json:"count,omitempty"`
147		Sum     *float64          `json:"sum,omitempty"`
148		Buckets []bucketOutput    `json:"buckets,omitempty"`
149	}
150	
151	type bucketOutput struct {
152		LE    float64 `json:"le"`
153		Count int64   `json:"count"`
154	}
155	
156	// query returns matching series as ready-to-encode outputs. A series matches
157	// when its name equals name exactly and it contains every selector label.
158	func (s *metricStore) query(name string, selector map[string]string) []seriesOutput {
159		s.mu.RLock()
160		defer s.mu.RUnlock()
161	
162		out := make([]seriesOutput, 0)
163		for _, cur := range s.series {
164			if cur.name != name {
165				continue
166			}
167			matched := true
168			for k, v := range selector {
169				got, ok := cur.labels[k]
170				if !ok || got != v {
171					matched = false
172					break
173				}
174			}
175			if !matched {
176				continue
177			}
178			item := seriesOutput{
179				Name:   cur.name,
180				Type:   cur.typ,
181				Labels: copyLabels(cur.labels),
182			}
183			switch cur.typ {
184			case "counter", "gauge":
185				v := cur.value
186				item.Value = &v
187			case "histogram":
188				c, sum := cur.count, cur.sum
189				item.Count = &c
190				item.Sum = &sum
191				item.Buckets = make([]bucketOutput, len(cur.bucketBounds))
192				for i, bound := range cur.bucketBounds {
193					item.Buckets[i] = bucketOutput{LE: bound, Count: cur.bucketCounts[i]}
194				}
195			}
196			out = append(out, item)
197		}
198	
199		sort.Slice(out, func(i, j int) bool {
200			return compareLabels(out[i].Labels, out[j].Labels) < 0
201		})
202		return out
203	}
204	
205	// compareLabels imposes a normalized lexicographic order on full label sets:
206	// keys are sorted, then (key, value) pairs are compared element-wise, and a
207	// shorter pair list sorts first when it is a prefix of a longer one.
208	func compareLabels(a, b map[string]string) int {
209		ka := sortedKeys(a)
210		kb := sortedKeys(b)
211		n := len(ka)
212		if len(kb) < n {
213			n = len(kb)
214		}
215		for i := 0; i < n; i++ {
216			if ka[i] != kb[i] {
217				return strings.Compare(ka[i], kb[i])
218			}
219			if a[ka[i]] != b[kb[i]] {
220				return strings.Compare(a[ka[i]], b[kb[i]])
221			}
222		}
223		switch {
224		case len(ka) < len(kb):
225			return -1
226		case len(ka) > len(kb):
227			return 1
228		default:
229			return 0
230		}
231	}
232	
233	func sortedKeys(m map[string]string) []string {
234		keys := make([]string, 0, len(m))
235		for k := range m {
236			keys = append(keys, k)
237		}
238		sort.Strings(keys)
239		return keys
240	}
241	
242	func copyLabels(in map[string]string) map[string]string {
243		out := make(map[string]string, len(in))
244		for k, v := range in {
245			out[k] = v
246		}
247		return out
248	}
249	
250	// seriesKey builds a collision-free identity from name + unordered labels.
251	// Name and label keys are restricted to [a-zA-Z0-9_] and cannot contain NUL,
252	// so length-prefixed values remove any ambiguity from arbitrary label values.
253	func seriesKey(name string, labels map[string]string) string {
254		var b strings.Builder
255		b.WriteString(name)
256		for _, k := range sortedKeys(labels) {
257			b.WriteByte(0)
258			b.WriteString(k)
259			b.WriteByte(0)
260			v := labels[k]
261			b.WriteString(strconv.Itoa(len(v)))
262			b.WriteByte(0)
263			b.WriteString(v)
264		}
265		return b.String()
266	}
267	
268	func equalBuckets(a, b []float64) bool {
269		if len(a) != len(b) {
270			return false
271		}
272		for i := range a {
273			if a[i] != b[i] {
274				return false
275			}
276		}
277		return true
278	}
279	
280	// Handler returns the HTTP surface served by SignalWatch.
281	func Handler() http.Handler {
282		mux := http.NewServeMux()
283		store := newMetricStore()
284	
285		mux.HandleFunc("/healthz", func(w http.ResponseWriter, r *http.Request) {
286			if r.Method != http.MethodGet {
287				w.Header().Set("Allow", http.MethodGet)
288				http.Error(w, `{"error":{"code":"method_not_allowed"}}`, http.StatusMethodNotAllowed)
289				return
290			}
291			w.Header().Set("Content-Type", "application/json; charset=utf-8")
292			_ = json.NewEncoder(w).Encode(health{Status: "ok", Service: "signalwatch", Version: Version})
293		})
294	
295		mux.HandleFunc(metricsPath, func(w http.ResponseWriter, r *http.Request) {
296			switch r.Method {
297			case http.MethodGet:
298				handleMetricsGet(w, r, store)
299			case http.MethodPost:
300				handleMetricsPost(w, r, store)
301			default:
302				w.Header().Set("Allow", "GET, POST")
303				writeAPIError(w, "method_not_allowed", http.StatusMethodNotAllowed)
304			}
305		})
306	
307		registerAlertHandlers(mux, store)
308	
309		return mux
310	}
311	
312	func handleMetricsPost(w http.ResponseWriter, r *http.Request, store *metricStore) {
313		mediaType, _, err := mime.ParseMediaType(r.Header.Get("Content-Type"))
314		if err != nil || mediaType != "application/json" {
315			writeAPIError(w, "unsupported_media_type", http.StatusUnsupportedMediaType)
316			return
317		}
318	
319		body, err := io.ReadAll(r.Body)
320		if err != nil {
321			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
322			return
323		}
324	
325		batch, ok := decodeMetricsBatch(body)
326		if !ok {
327			writeAPIError(w, "invalid_metrics", http.StatusBadRequest)
328			return
329		}
330	
331		if !store.checkAndApply(batch) {
332			writeAPIError(w, "metric_conflict", http.StatusConflict)
333			return
334		}
335	
336		w.Header().Set("Content-Type", "application/json; charset=utf-8")
337		w.WriteHeader(http.StatusAccepted)
338		_ = json.NewEncoder(w).Encode(map[string]int{"accepted": len(batch)})
339	}
340	
341	type metricsEnvelope struct {
342		Samples *[]json.RawMessage `json:"samples"`
343	}
344	
345	type rawSample struct {
346		Name    *string            `json:"name"`
347		Type    *string            `json:"type"`
348		Labels  *map[string]string `json:"labels"`
349		Value   *float64           `json:"value"`
350		Buckets *[]float64         `json:"buckets"`
351	}
352	
353	// decodeMetricsBatch performs every format and value check. It never returns a
354	// partially validated batch.
355	func decodeMetricsBatch(body []byte) ([]validatedSample, bool) {
356		var env metricsEnvelope
357		if !strictDecode(body, &env) || env.Samples == nil || len(*env.Samples) == 0 {
358			return nil, false
359		}
360	
361		batch := make([]validatedSample, 0, len(*env.Samples))
362		for _, raw := range *env.Samples {
363			var sm rawSample
364			if !strictDecode(raw, &sm) {
365				return nil, false
366			}
367			if sm.Name == nil || sm.Type == nil || sm.Labels == nil || sm.Value == nil {
368				return nil, false
369			}
370			name, typ := *sm.Name, *sm.Type
371			if !identPattern.MatchString(name) {
372				return nil, false
373			}
374			if typ != "counter" && typ != "gauge" && typ != "histogram" {
375				return nil, false
376			}
377			labels := *sm.Labels
378			if labels == nil {
379				return nil, false // explicit null labels
380			}
381			for k := range labels {
382				if !identPattern.MatchString(k) {
383					return nil, false
384				}
385			}
386			value := *sm.Value
387			if math.IsNaN(value) || math.IsInf(value, 0) {
388				return nil, false // encoding/json already rejects NaN/Inf tokens
389			}
390			if typ == "counter" && value < 0 {
391				return nil, false
392			}
393	
394			var buckets []float64
395			if typ == "histogram" {
396				if sm.Buckets == nil || !validBuckets(*sm.Buckets) {
397					return nil, false
398				}
399				buckets = append([]float64(nil), (*sm.Buckets)...)
400			} else if sm.Buckets != nil {
401				return nil, false // buckets only valid on histograms
402			}
403	
404			batch = append(batch, validatedSample{
405				key:     seriesKey(name, labels),
406				name:    name,
407				typ:     typ,
408				labels:  copyLabels(labels),
409				value:   value,
410				buckets: buckets,
411			})
412		}
413		return batch, true
414	}
415	
416	func validBuckets(buckets []float64) bool {
417		if len(buckets) == 0 {
418			return false
419		}
420		prev := math.Inf(-1)
421		for _, b := range buckets {
422			if math.IsNaN(b) || math.IsInf(b, 0) || b <= prev {
423				return false
424			}
425			prev = b
426		}
427		return true
428	}
429	
430	// strictDecode decodes JSON, rejecting unknown fields, multiple/ trailing
431	// values and non-object payloads for struct targets.
432	func strictDecode(data []byte, target any) bool {
433		dec := json.NewDecoder(bytes.NewReader(data))
434		dec.DisallowUnknownFields()
435		if err := dec.Decode(target); err != nil {
436			return false
437		}
438		var extra json.RawMessage
439		if err := dec.Decode(&extra); err != io.EOF {
440			return false
441		}
442		return true
443	}
444	
445	func handleMetricsGet(w http.ResponseWriter, r *http.Request, store *metricStore) {
446		values, err := url.ParseQuery(r.URL.RawQuery)
447		if err != nil {
448			writeAPIError(w, "invalid_query", http.StatusBadRequest)
449			return
450		}
451	
452		names := values["name"]
453		if len(names) == 0 || !identPattern.MatchString(names[0]) {
454			writeAPIError(w, "invalid_query", http.StatusBadRequest)
455			return
456		}
457	
458		selector := make(map[string]string)
459		for key, vals := range values {
460			if !strings.HasPrefix(key, "label.") {
461				continue
462			}
463			labelKey := strings.TrimPrefix(key, "label.")
464			if !identPattern.MatchString(labelKey) {
465				writeAPIError(w, "invalid_query", http.StatusBadRequest)
466				return
467			}
468			for _, v := range vals[1:] {
469				if v != vals[0] {
470					writeAPIError(w, "invalid_query", http.StatusBadRequest)
471					return
472				}
473			}
474			selector[labelKey] = vals[0]
475		}
476	
477		seriesList := store.query(names[0], selector)
478		w.Header().Set("Content-Type", "application/json; charset=utf-8")
479		_ = json.NewEncoder(w).Encode(map[string]any{"series": seriesList})
480	}
481	
482	func writeAPIError(w http.ResponseWriter, code string, status int) {
483		w.Header().Set("Content-Type", "application/json; charset=utf-8")
484		w.WriteHeader(status)
485		_ = json.NewEncoder(w).Encode(map[string]any{"error": map[string]string{"code": code}})
486	}
