	// Index currently active silences by the rule ids they cover. Stored
	// rule_ids are sorted and de-duplicated, so silence ids arrive here in
	// lexicographic order and only need per-rule sorting below.
	activeByRule := make(map[string][]string)
	for _, sil := range s.silences {
		if !sil.activeAt(now) {
			continue
		}
		for _, ruleID := range sil.ruleIDs {
			activeByRule[ruleID] = append(activeByRule[ruleID], sil.id)
		}
	}

	out := make([]alertOutput, 0, len(rules))
	for _, r := range rules {
		al := alertOutput{ID: r.id, State: "inactive", SilenceIDs: []string{}}

		var value float64
		if r.kind == "threshold" {
			sum, ok := s.selectorSum(r.left)
			if !ok {
				al.State = "no_data"
				out = append(out, al)
				continue
			}
			value = sum
		} else {
			num, numOK := s.selectorSum(r.left)
			den, denOK := s.selectorSum(r.right)
			if !numOK || !denOK || den == 0 {
				al.State = "no_data"
				out = append(out, al)
				continue
			}
			value = num / den
		}

		v := value
		al.Value = &v
		if compareHolds(r.operator, value, r.threshold) {
			al.State = "firing"
			if hits := activeByRule[r.id]; len(hits) > 0 {
				al.Silenced = true
				al.SilenceIDs = append(al.SilenceIDs, hits...)
				sort.Strings(al.SilenceIDs)
			}
		}
		out = append(out, al)
	}
	return out
}

